51	
52	import jakarta.transaction.Transactional;
53	
54	/**
55	 * @author Vitaliy Fedoriv
56	 */
57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email validation: a non-empty local part, a single '@', and a
65	     * domain with at least one dot-separated label ending in a letter-only TLD.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
69	
70	    /** Dedicated audit logger for owner lifecycle side-effects. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    /**
92	     * Normalise a raw telephone number to E.164 form.
93	     *
94	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
95	     * code are kept when present; otherwise country code '+61' is assumed and a
96	     * single leading '0' is dropped from the national digits. The result must have
97	     * between 8 and 15 digits after the '+'.
98	     *
99	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
100	     */
101	    static String toE164(String raw) {
102	        if (raw == null) {
103	            return null;
104	        }
105	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
106	        String digits;
107	        if (cleaned.startsWith("+")) {
108	            digits = cleaned.substring(1);
109	        } else {
110	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
111	            digits = "61" + national;
112	        }
113	        if (!digits.matches("[0-9]{8,15}")) {
114	            return null;
115	        }
116	        return "+" + digits;
117	    }
118	
119	    /**
120	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
121	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
122	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
123	     * input normalises to the empty string.
124	     */
125	    private static String normaliseIdentity(String value) {
126	        if (value == null) {
127	            return "";
128	        }
129	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
130	    }
131	
132	    /**
133	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
134	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
135	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
136	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
137	     * that is both stored and used for every address comparison.
138	     */
139	    static String normaliseAddress(String value) {
140	        if (value == null) {
141	            return "";
142	        }
143	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
144	        if (collapsed.isEmpty()) {
145	            return "";
146	        }
147	        String[] tokens = collapsed.split(" ");
148	        StringBuilder result = new StringBuilder();
149	        for (int i = 0; i < tokens.length; i++) {
150	            if (i > 0) {
151	                result.append(' ');
152	            }
153	            result.append(expandAddressAbbreviation(tokens[i]));
154	        }
155	        return result.toString();
156	    }
157	
158	    /**
159	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
160	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
161	     * returned unchanged.
162	     */
163	    private static String expandAddressAbbreviation(String token) {
164	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
165	        return switch (core) {
166	            case "ST" -> "STREET";
167	            case "RD" -> "ROAD";
168	            case "AVE" -> "AVENUE";
169	            default -> token;
170	        };
171	    }
172	
173	    /**
174	     * Derive the stable, shared household identifier for owners sharing a household. It is a
175	     * deterministic UUID over the normalised last-name and address, so every owner in the same
176	     * household resolves to the same value regardless of the order in which they were created.
177	     */
178	    private static String householdId(String lastNameKey, String addressKey) {
179	        String seed = lastNameKey + "�" + addressKey;
180	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
181	    }
182	
183	    /**
184	     * Build the customer code for a new owner as {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
185	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
186	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
187	     * owners already in that city at the time the owner was created.
188	     */
189	    private String nextCustomerCode(String city, String lastName) {
190	        String city3 = prefix3(city);
191	        String last3 = prefix3(lastName);
192	        String cityKey = normaliseIdentity(city);
193	        int sequence = (int) this.clinicService.findAllOwners().stream()
194	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
195	            .count() + 1;
196	        return String.format("%s-%s-%04d", city3, last3, sequence);
197	    }
198	
199	    /**
200	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
201	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
202	     */
203	    static LocalDate toBusinessDay(LocalDate date) {
204	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
205	            date = date.plusDays(1);
206	        }
207	        return date;
208	    }
209	
210	    /**
211	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
212	     * using the same per-day accumulation path as the daily create-limit rule.
213	     */
214	    private long ownersCreatedOn(LocalDate registrationDate) {
215	        LocalDate day = toBusinessDay(registrationDate);
216	        return this.clinicService.findAllOwners().stream()
217	            .map(Owner::getRegistrationDate)
218	            .filter(existing -> existing != null)
219	            .map(OwnerRestControllerV1::toBusinessDay)
220	            .filter(day::equals)
221	            .count();
222	    }
223	
224	    /**
225	     * Resolve an owner's membership tier. It is {@code "GOLD"} when the owner's household — the owners
226	     * sharing this owner's {@code householdId} — has three or more members; otherwise the base
227	     * BRONZE/SILVER rule (see {@link OwnerMapper#formatMembershipTier}) applies. Owners without a
228	     * household id can never be GOLD.
229	     */
230	    private String membershipTier(Owner owner) {
231	        String householdId = owner.getHouseholdId();
232	        if (householdId != null) {
233	            long members = this.clinicService.findAllOwners().stream()
234	                .filter(existing -> householdId.equals(existing.getHouseholdId()))
235	                .count();
236	            if (members >= 3) {
237	                return "GOLD";
238	            }
239	        }
240	        return ownerMapper.formatMembershipTier(owner);
241	    }
242	
243	    /** Upper-cased first three characters of {@code value} (fewer if it is shorter); "" when null. */
244	    private static String prefix3(String value) {
245	        String letters = value == null ? "" : value;
246	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase();
247	    }
248	
249	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
250	    @Override
251	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
252	        Collection<Owner> owners;
253	        if (lastName != null) {
254	            owners = this.clinicService.findOwnerByLastName(lastName);
255	        } else {
256	            owners = this.clinicService.findAllOwners();
257	        }
258	        if (owners.isEmpty()) {
259	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	        }
261	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner == null) {
269	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	        }
271	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
272	        ownerDto.setMembershipTier(membershipTier(owner));
273	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
274	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
275	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
276	    }
277	
278	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
279	    @Override
280	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
281	        String telephone = toE164(ownerFieldsDto.getTelephone());
282	        if (telephone == null) {
283	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
284	        }
285	        String email = ownerFieldsDto.getEmail();
286	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
287	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
288	        }
289	        String address = normaliseAddress(ownerFieldsDto.getAddress());
290	        if (address.isEmpty()) {
291	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
292	        }
293	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
294	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
295	        LocalDate registrationDate = toBusinessDay(effectiveDate);
296	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
297	            .map(Owner::getRegistrationDate)
298	            .filter(existing -> existing != null)
299	            .map(OwnerRestControllerV1::toBusinessDay)
300	            .filter(registrationDate::equals)
301	            .count();
302	        if (ownersCreatedThatDay >= 100) {
303	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
304	        }
305	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
306	        long ownersInCity = this.clinicService.findAllOwners().stream()
307	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
308	            .count();
309	        if (ownersInCity >= 50) {
310	            return new ResponseEntity<>(HttpStatus.CONFLICT);
311	        }
312	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
313	            .map(Owner::getTelephone)
314	            .map(OwnerRestControllerV1::toE164)
315	            .filter(existing -> existing != null)
316	            .anyMatch(telephone::equals);
317	        if (telephoneInUse) {
318	            return new ResponseEntity<>(HttpStatus.CONFLICT);
319	        }
320	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
321	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
322	        String addressKey = address;
323	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
324	            .filter(existing ->
325	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
326	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
327	            .toList();
328	        if (!householdMembers.isEmpty() && !sharesHousehold) {
329	            return new ResponseEntity<>(HttpStatus.CONFLICT);
330	        }
331	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
332	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
333	            .filter(existing ->
334	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
335	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
336	            .count();
337	        HttpHeaders headers = new HttpHeaders();
338	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
339	        owner.setNamesakeCount(namesakeCount);
340	        owner.setAddress(address);
341	        owner.setTelephone(telephone);
342	        owner.setEmail(email == null ? null : email.toLowerCase());
343	        owner.setRegistrationDate(registrationDate);
344	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
345	        if (sharesHousehold && !householdMembers.isEmpty()) {
346	            String householdId = householdId(lastNameKey, addressKey);
347	            owner.setHouseholdId(householdId);
348	            for (Owner member : householdMembers) {
349	                if (member.getHouseholdId() == null) {
350	                    member.setHouseholdId(householdId);
351	                    this.clinicService.saveOwner(member);
352	                }
353	            }
354	        }
355	        this.clinicService.saveOwner(owner);
356	        AUDIT.info("owner created: id={} customerCode={} registrationDate={}",
357	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
358	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
359	        ownerDto.setMembershipTier(membershipTier(owner));
360	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
361	        headers.setLocation(UriComponentsBuilder.newInstance()
362	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
363	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
364	    }
365	
366	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
367	    @Override
368	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
369	        String telephone = toE164(ownerFieldsDto.getTelephone());
370	        if (telephone == null) {
371	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
372	        }
373	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
374	        if (currentOwner == null) {
375	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
376	        }
377	        String email = ownerFieldsDto.getEmail();
378	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
379	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
380	        }
381	        currentOwner.setAddress(ownerFieldsDto.getAddress());
382	        currentOwner.setCity(ownerFieldsDto.getCity());
383	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
384	        currentOwner.setLastName(ownerFieldsDto.getLastName());
385	        currentOwner.setTelephone(telephone);
386	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
387	        this.clinicService.saveOwner(currentOwner);
388	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
389	    }
