391	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
392	    @Transactional
393	    @Override
394	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
395	        Owner owner = this.clinicService.findOwnerById(ownerId);
396	        if (owner == null) {
397	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
398	        }
399	        this.clinicService.deleteOwner(owner);
400	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
401	    }
