403	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
404	    @Override
405	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
406	        Owner owner = this.clinicService.findOwnerById(ownerId);
407	        if (owner == null) {
408	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
409	        }
410	        HttpHeaders headers = new HttpHeaders();
411	        Pet pet = petMapper.toPet(petFieldsDto);
412	        owner.setId(ownerId);
413	        pet.setOwner(owner);
414	        pet.getType().setName(null);
415	        this.clinicService.savePet(pet);
416	        PetDto petDto = petMapper.toPetDto(pet);
417	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
418	            .buildAndExpand(pet.getId()).toUri());
419	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
420	    }
421	
422	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
423	    @Override
424	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
425	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
426	        if (currentOwner != null) {
427	            Pet currentPet = this.clinicService.findPetById(petId);
428	            if (currentPet != null) {
429	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
430	                currentPet.setName(petFieldsDto.getName());
431	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
432	                this.clinicService.savePet(currentPet);
433	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
434	            }
435	        }
436	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
437	    }
