439	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
440	    @Override
441	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
442	        HttpHeaders headers = new HttpHeaders();
443	        Visit visit = visitMapper.toVisit(visitFieldsDto);
444	        Pet pet = new Pet();
445	        pet.setId(petId);
446	        visit.setPet(pet);
447	        this.clinicService.saveVisit(visit);
448	        VisitDto visitDto = visitMapper.toVisitDto(visit);
449	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
450	            .buildAndExpand(visit.getId()).toUri());
451	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
452	    }
