455	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
456	    @Override
457	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
458	        Owner owner = this.clinicService.findOwnerById(ownerId);
459	        if (owner != null) {
460	            Pet pet = owner.getPet(petId);
461	            if (pet != null) {
462	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
463	            }
464	        }
